package matteroverdrive.block;import matteroverdrive.blockentity.StarMapBlockEntity;import matteroverdrive.registry.ModBlockEntities;import net.minecraft.core.BlockPos;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;import net.minecraftforge.network.NetworkHooks;import javax.annotation.Nullable;
public class StarMapBlock extends BaseEntityBlock{public StarMapBlock(Properties p){super(p);}@Override public RenderShape getRenderShape(BlockState s){return RenderShape.MODEL;}@Nullable @Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return new StarMapBlockEntity(p,s);}@Override public InteractionResult use(BlockState s,Level l,BlockPos p,Player player,InteractionHand h,BlockHitResult hit){if(!l.isClientSide&&player instanceof ServerPlayer sp&&l.getBlockEntity(p)instanceof StarMapBlockEntity map){map.link(sp);NetworkHooks.openScreen(sp,map,p);}return InteractionResult.sidedSuccess(l.isClientSide);}}